-- legal topics (only inserted when missing: reviewed content is never overwritten)
insert into public.legal_topics (jurisdiction_code, topic, title_ru, summary_ru, points_ru, sources, status, sort_order) values ('TH', 'ownership', 'Что может купить иностранец', 'Квартиру (кондо) можно оформить в собственность в пределах иностранной квоты здания; для вилл и земли обычно используют долгосрочную аренду земли или компанию, и каждая схема требует независимой юридической проверки.', '["Кондо: доля иностранцев в здании ограничена (как правило, 49% площади).","Земля в собственность иностранцу, как правило, недоступна; распространена регистрируемая аренда земли на длительный срок.","Схемы «через компанию» несут юридические риски и должны быть проверены юристом."]'::jsonb, '[{"title":"Department of Lands (Таиланд)","url":"https://www.dol.go.th/"}]'::jsonb, 'draft', 10) on conflict (jurisdiction_code, topic) do nothing;
insert into public.legal_topics (jurisdiction_code, topic, title_ru, summary_ru, points_ru, sources, status, sort_order) values ('TH', 'process', 'Порядок покупки новостройки', 'Бронирование, договор купли-продажи (SPA) с графиком платежей по этапам стройки, приёмка объекта и регистрация прав в земельном департаменте.', '["Платежи должны быть привязаны к подтверждённым этапам стройки.","Платите только на счёт юридического лица, указанного в договоре.","Для кондо подтверждение поступления средств из-за границы нужно при регистрации (форма FET)."]'::jsonb, '[{"title":"Department of Lands (Таиланд)","url":"https://www.dol.go.th/"}]'::jsonb, 'draft', 20) on conflict (jurisdiction_code, topic) do nothing;
insert into public.legal_topics (jurisdiction_code, topic, title_ru, summary_ru, points_ru, sources, status, sort_order) values ('TH', 'taxes', 'Налоги и сборы', 'При передаче права и при владении возникают сборы и налоги; их размер зависит от срока владения, оценочной стоимости и статуса владельца.', '["При регистрации: сбор за передачу права, специальный бизнес-налог или гербовый сбор, подоходный налог продавца.","При владении: налог на землю и строения, взносы на содержание общих зон для кондо.","Доход от аренды облагается налогом: резидентство и международные соглашения нужно разбирать с консультантом."]'::jsonb, '[{"title":"Revenue Department (Таиланд)","url":"https://www.rd.go.th/"}]'::jsonb, 'draft', 30) on conflict (jurisdiction_code, topic) do nothing;
insert into public.legal_topics (jurisdiction_code, topic, title_ru, summary_ru, points_ru, sources, status, sort_order) values ('TH', 'disputes', 'Просрочки и споры с застройщиком', 'Порядок действий определяется договором: уведомление в установленной форме, переговоры, затем судебные или арбитражные процедуры с независимым тайским юристом.', '["Сохраните договор, график платежей, платёжки и переписку.","Уведомляйте застройщика письменно и подтверждайте получение.","Следите за сроками давности: не откладывайте обращение."]'::jsonb, '[]'::jsonb, 'draft', 40) on conflict (jurisdiction_code, topic) do nothing;
insert into public.legal_topics (jurisdiction_code, topic, title_ru, summary_ru, points_ru, sources, status, sort_order) values ('TH', 'visa', 'Виза и проживание', 'Покупка недвижимости сама по себе не даёт вида на жительство; для длительного проживания рассматривают отдельные визовые программы, условия которых меняются.', '["Проверяйте актуальные требования на официальных сайтах миграционных органов."]'::jsonb, '[]'::jsonb, 'draft', 50) on conflict (jurisdiction_code, topic) do nothing;
insert into public.legal_topics (jurisdiction_code, topic, title_ru, summary_ru, points_ru, sources, status, sort_order) values ('VN', 'ownership', 'Что может купить иностранец', 'Иностранцы, как правило, могут приобретать жильё в проектах коммерческого жилья на ограниченный срок с возможностью продления и в пределах квот на здание и район; земля принадлежит государству, частные лица получают права пользования.', '["Срок права для иностранца ограничен законом (как правило, до 50 лет с продлением).","Действуют квоты на долю квартир в здании и количество домов в районе.","Точные условия определяются действующим Законом о жилье и должны быть проверены вьетнамским юристом."]'::jsonb, '[{"title":"Министерство строительства Вьетнама","url":"https://moc.gov.vn/"}]'::jsonb, 'draft', 10) on conflict (jurisdiction_code, topic) do nothing;
insert into public.legal_topics (jurisdiction_code, topic, title_ru, summary_ru, points_ru, sources, status, sort_order) values ('VN', 'process', 'Покупка новостройки', 'Покупка квартир в строящемся доме допускается у застройщиков, чей проект соответствует установленным условиям продажи жилья в будущем (включая банковскую гарантию), по договору с застройщиком.', '["Проверяйте у юриста, что проект вправе продавать жильё на этапе строительства.","Уточните график платежей, условия гарантии и порядок передачи сертификата прав."]'::jsonb, '[]'::jsonb, 'draft', 20) on conflict (jurisdiction_code, topic) do nothing;
insert into public.legal_topics (jurisdiction_code, topic, title_ru, summary_ru, points_ru, sources, status, sort_order) values ('VN', 'taxes', 'Налоги и сборы', 'Раздел готовится вместе с местным налоговым консультантом.', '[]'::jsonb, '[]'::jsonb, 'planned', 30) on conflict (jurisdiction_code, topic) do nothing;
insert into public.legal_topics (jurisdiction_code, topic, title_ru, summary_ru, points_ru, sources, status, sort_order) values ('VN', 'disputes', 'Споры с застройщиком', 'Раздел готовится вместе с местным юристом: порядок претензий, переговоры, суд и арбитраж.', '[]'::jsonb, '[]'::jsonb, 'planned', 40) on conflict (jurisdiction_code, topic) do nothing;
